-- Pro(D)Track · Esquema de la base de datos (PostgreSQL) · basado en el ERD v2
--
-- Equivalencias con el diccionario de datos:
--   int autoincremental  -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--   bit                  -> BOOLEAN (1/0 = TRUE/FALSE)
--   datetime             -> TIMESTAMP
--   decimal(5,4), date, time y varchar(n) se conservan igual.

DROP TABLE IF EXISTS Paro, Registro, Turno, CategoriaParo, TipoTurno, Modelo, Maquina, Usuario CASCADE;

-- ---------- Seguridad ----------

CREATE TABLE Usuario (
    Id_Usuario      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NumeroEmpleado  VARCHAR(20)  NOT NULL UNIQUE,
    Nombre          VARCHAR(100) NOT NULL,
    PasswordHash    VARCHAR(255) NOT NULL,
    Rol             VARCHAR(12)  NOT NULL CHECK (Rol IN ('operador', 'tecnico', 'supervisor')),
    Activo          BOOLEAN      NOT NULL DEFAULT TRUE,
    CreadoEn        TIMESTAMP    NOT NULL DEFAULT NOW()
);

-- ---------- Catálogos ----------

CREATE TABLE Maquina (
    Id_Maquina  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Codigo      VARCHAR(20)  NOT NULL UNIQUE,
    Nombre      VARCHAR(100) NOT NULL,
    Area        VARCHAR(60),
    Activa      BOOLEAN      NOT NULL DEFAULT TRUE
);

CREATE TABLE Modelo (
    Id_Modelo    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NumeroParte  VARCHAR(40)  NOT NULL UNIQUE,
    Nombre       VARCHAR(100) NOT NULL,
    UphEstandar  INTEGER      NOT NULL CHECK (UphEstandar > 0),
    Activo       BOOLEAN      NOT NULL DEFAULT TRUE
);

CREATE TABLE TipoTurno (
    Id_TipoTurno        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Clave               VARCHAR(5) NOT NULL UNIQUE CHECK (Clave IN ('T1', 'T2')),
    HoraInicio          TIME       NOT NULL,
    HoraFin             TIME       NOT NULL,
    MinutosProgramados  INTEGER    NOT NULL CHECK (MinutosProgramados > 0)
);

CREATE TABLE CategoriaParo (
    Id_CategoriaParo  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Nombre            VARCHAR(60) NOT NULL UNIQUE,
    Planeado          BOOLEAN     NOT NULL DEFAULT FALSE,
    Activo            BOOLEAN     NOT NULL DEFAULT TRUE
);

-- ---------- Operación ----------

CREATE TABLE Turno (
    Id_Turno        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Id_Maquina      INTEGER      NOT NULL REFERENCES Maquina (Id_Maquina),
    Id_TipoTurno    INTEGER      NOT NULL REFERENCES TipoTurno (Id_TipoTurno),
    Fecha           DATE         NOT NULL,
    Estado          VARCHAR(10)  NOT NULL DEFAULT 'activo' CHECK (Estado IN ('activo', 'cerrado')),
    Id_Tecnico      INTEGER      NOT NULL REFERENCES Usuario (Id_Usuario),
    Id_Operador     INTEGER               REFERENCES Usuario (Id_Usuario),
    AbiertoEn       TIMESTAMP    NOT NULL DEFAULT NOW(),
    CerradoEn       TIMESTAMP    CHECK (CerradoEn >= AbiertoEn),
    Disponibilidad  DECIMAL(5,4) CHECK (Disponibilidad BETWEEN 0 AND 1),
    Rendimiento     DECIMAL(5,4) CHECK (Rendimiento BETWEEN 0 AND 1),
    Calidad         DECIMAL(5,4) CHECK (Calidad BETWEEN 0 AND 1),
    OEE             DECIMAL(5,4) CHECK (OEE BETWEEN 0 AND 1),
    Observaciones   VARCHAR(300),
    UNIQUE (Id_Maquina, Fecha, Id_TipoTurno)
);
CREATE INDEX ix_turno_estado ON Turno (Estado);

CREATE TABLE Registro (
    Id_Registro         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Id_Turno            INTEGER      NOT NULL REFERENCES Turno (Id_Turno),
    NumeroHora          INTEGER      NOT NULL CHECK (NumeroHora BETWEEN 1 AND 12),
    HoraInicio          TIMESTAMP    NOT NULL,
    MinutosProgramados  INTEGER      NOT NULL DEFAULT 60 CHECK (MinutosProgramados BETWEEN 1 AND 60),
    Id_Modelo           INTEGER      NOT NULL REFERENCES Modelo (Id_Modelo),
    UphEstandar         INTEGER      NOT NULL CHECK (UphEstandar > 0),
    UphPlaneado         INTEGER      NOT NULL CHECK (UphPlaneado >= 0),
    UphReal             INTEGER      CHECK (UphReal >= 0),
    BuenasPrimera       INTEGER      CHECK (BuenasPrimera BETWEEN 0 AND UphReal),
    Motivo              VARCHAR(300),
    Contramedida        VARCHAR(300),
    Id_CapturadoPor     INTEGER      REFERENCES Usuario (Id_Usuario),
    CapturadoEn         TIMESTAMP,
    Id_EditadoPor       INTEGER      REFERENCES Usuario (Id_Usuario),
    EditadoEn           TIMESTAMP    CHECK (EditadoEn >= CapturadoEn),
    UNIQUE (Id_Turno, NumeroHora),
    -- Motivo obligatorio cuando no se cumplió la meta de la hora
    CHECK (UphReal IS NULL OR UphReal >= UphPlaneado OR Motivo IS NOT NULL)
);
CREATE INDEX ix_registro_modelo ON Registro (Id_Modelo);

CREATE TABLE Paro (
    Id_Paro           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    Id_Turno          INTEGER   NOT NULL REFERENCES Turno (Id_Turno),
    Id_CategoriaParo  INTEGER   NOT NULL REFERENCES CategoriaParo (Id_CategoriaParo),
    HoraInicio        TIMESTAMP NOT NULL,
    HoraFin           TIMESTAMP CHECK (HoraFin >= HoraInicio),
    Descripcion       VARCHAR(300),
    Id_RegistradoPor  INTEGER   NOT NULL REFERENCES Usuario (Id_Usuario)
);
CREATE INDEX ix_paro_turno     ON Paro (Id_Turno);
CREATE INDEX ix_paro_categoria ON Paro (Id_CategoriaParo);
